Here is the commit message:
apparmor: avoid per-cpu hold underflow in aa_get_buffer

When aa_get_buffer() pulls from the per-cpu list it unconditionally
decrements cache->hold. If hold reaches 0 while count is still non-zero,
the unsigned decrement wraps to UINT_MAX. This keeps hold non-zero for a
very long time, so aa_put_buffer() never returns buffers to the global
list, which can starve other CPUs and force repeated kmalloc(aa_g_path_max)
allocations.

Guard the decrement so hold never underflows.
Fixes: ea9bae12d028 ("apparmor: cache buffers on percpu list if there is lock contention")

Signed-off-by: Zhengmian Hu <huzhengmian@gmail.com>
Signed-off-by: John Johansen <john.johansen@canonical.com>

Here is the root cause:
In `aa_get_buffer()`, when the per-CPU cache's `hold` counter is 0 but `count` is still non-zero, the unconditional `cache->hold--` causes an unsigned underflow (wrapping to `UINT_MAX`). This prevents `aa_put_buffer()` from ever returning buffers to the global list, starving other CPUs and forcing repeated `kmalloc(aa_g_path_max)` allocations.

Here is the patch:

 char *aa_get_buffer(bool in_atomic)
 {
 	union aa_buffer *aa_buf;
 	struct aa_local_cache *cache;
 	bool try_again = true;
 	gfp_t flags = (GFP_KERNEL | __GFP_RETRY_MAYFAIL | __GFP_NOWARN);

 	/* use per cpu cached buffers first */
 	cache = get_cpu_ptr(&aa_local_buffers);
 	if (!list_empty(&cache->head)) {
 		aa_buf = list_first_entry(&cache->head, union aa_buffer, list);
 		list_del(&aa_buf->list);
-		cache->hold--;
+		if (cache->hold)
+			cache->hold--;
 		cache->count--;
 		put_cpu_ptr(&aa_local_buffers);
 		return &aa_buf->buffer[0];
 	}
 	put_cpu_ptr(&aa_local_buffers);

 	if (!spin_trylock(&aa_buffers_lock)) {
 		cache = get_cpu_ptr(&aa_local_buffers);
 		cache->hold += 1;
 		put_cpu_ptr(&aa_local_buffers);
 		spin_lock(&aa_buffers_lock);
 	} else {
 		cache = get_cpu_ptr(&aa_local_buffers);
 		put_cpu_ptr(&aa_local_buffers);
 	}
 retry:
 	if (buffer_count > reserve_count ||
 	    (in_atomic && !list_empty(&aa_global_buffers))) {
 		aa_buf = list_first_entry(&aa_global_buffers, union aa_buffer,
 					  list);
 		list_del(&aa_buf->list);
 		buffer_count--;
 		spin_unlock(&aa_buffers_lock);
 		return aa_buf->buffer;
 	}
 	if (in_atomic) {
 		/*
 		 * out of reserve buffers and in atomic context so increase
 		 * how many buffers to keep in reserve
 		 */
 		reserve_count++;
 		flags = GFP_ATOMIC;
 	}
 	spin_unlock(&aa_buffers_lock);

 	if (!in_atomic)
 		might_sleep();
 	aa_buf = kmalloc(aa_g_path_max, flags);
 	if (!aa_buf) {
 		if (try_again) {
 			try_again = false;
 			spin_lock(&aa_buffers_lock);
 			goto retry;
 		}
 		pr_warn_once("AppArmor: Failed to allocate a memory buffer.\n");
 		return NULL;
 	}
 	return aa_buf->buffer;
 }



